mapper.select:
SELECT u.id AS user_id, u.tenant_id, r.role_code, r.role_scope, r.status AS role_status, p.permission_code FROM sys_user u INNER JOIN sys_user_role ur ON ur.user_id = u.id AND ((u.tenant_id IS NULL AND ur.tenant_id IS NULL) OR (u.tenant_id IS NOT NULL AND ur.tenant_id = u.tenant_id)) INNER JOIN sys_role r ON r.id = ur.role_id AND r.status = 'ACTIVE' AND r.deleted = 0 LEFT JOIN sys_role_permission rp ON rp.role_id = r.id LEFT JOIN sys_permission p ON p.id = rp.permission_id WHERE u.id = #{userId} AND u.status = 'ACTIVE' AND u.deleted = 0 AND r.role_scope = #{roleScope}
AND u.tenant_id IS NULL AND r.tenant_id IS NULL
AND u.tenant_id = #{tenantId} AND r.tenant_id = #{tenantId}
